/**
 * The app icons (256 px) as data URIs for the 3D hero.
 * WebGL refuses image textures loaded from file://, so the page also works when index.html is opened directly.
 * Regenerate from assets/icons/*.png if the icons change.
 */
window.OpenSite = window.OpenSite || {};
window.OpenSite.iconData = {
  notes: "data:image/png;base64,",
  calendar: "data:image/png;base64,",
  kanban: "data:image/png;base64,",
  launcher: "data:image/png;base64,",
};
